{
  "findings": [
    {
      "check_id": "CKV_AWS_248",
      "title": "Ensure that an AMI is not publicly accessible",
      "resource": "aws_ami.pass",
      "severity": "MEDIUM",
      "explanation": "The AMI is not explicitly set to be private, which could lead to unintended public exposure."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }

  lifecycle {
    create_before_destroy = true
  }

  # Added to prevent public exposure
  launch_permission {
    user_id = []
  }
}",
  "fix_summary": "Added launch_permission block with an empty user_id list to prevent the AMI from being publicly accessible by default."
}
